<?php require_once '../includes/db.php';require_once '../includes/functions.php';admin_required();$id=(int)($_GET['id']??0);$p=['name'=>'','category'=>'Accessories','description'=>'','price'=>'','stock'=>'','image_url'=>'assets/product.svg','active'=>1];if($id){$s=$conn->prepare("SELECT * FROM products WHERE id=?");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p)exit('Product not found');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();foreach(['name','category','description','image_url'] as $f)$p[$f]=trim($_POST[$f]??'');$p['price']=$_POST['price']??'';$p['stock']=$_POST['stock']??'';$p['active']=isset($_POST['active'])?1:0;if(mb_strlen($p['name'])<2)$errors[]='Name must be at least 2 characters.';if(!$p['category'])$errors[]='Category is required.';if(!is_numeric($p['price'])||(float)$p['price']<=0)$errors[]='Enter a positive price.';if(filter_var($p['stock'],FILTER_VALIDATE_INT)===false||(int)$p['stock']<0)$errors[]='Stock must be zero or more.';if(!$errors){$price=(float)$p['price'];$stock=(int)$p['stock'];if($id){$s=$conn->prepare("UPDATE products SET name=?,category=?,description=?,price=?,stock=?,image_url=?,active=? WHERE id=?");$s->bind_param('sssdisii',$p['name'],$p['category'],$p['description'],$price,$stock,$p['image_url'],$p['active'],$id);}else{$s=$conn->prepare("INSERT INTO products(name,category,description,price,stock,image_url,active) VALUES(?,?,?,?,?,?,?)");$s->bind_param('sssdisi',$p['name'],$p['category'],$p['description'],$price,$stock,$p['image_url'],$p['active']);}$s->execute();flash('Product saved successfully.');header('Location: products.php');exit;}}$title=$id?'Edit product':'Add product';$adminPage=true;include '../includes/header.php';?><div class="heading"><div><small>CATALOGUE</small><h2><?=$id?'Edit product':'Add product'?></h2></div><a href="products.php">← Back</a></div><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><?php foreach($errors as $err):?><div class="flash"><?=e($err)?></div><?php endforeach;?><label>Product name<input name="name" required minlength="2" value="<?=e($p['name'])?>"></label><label>Category<input name="category" required value="<?=e($p['category'])?>"></label><label>Description<textarea name="description" rows="4"><?=e($p['description'])?></textarea></label><div class="row"><label>Price (₹)<input type="number" name="price" min=".01" step=".01" required value="<?=e($p['price'])?>"></label><label>Stock<input type="number" name="stock" min="0" required value="<?=e($p['stock'])?>"></label></div><label>Image URL or local path<input name="image_url" value="<?=e($p['image_url'])?>"></label><label class="check"><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> Visible in storefront</label><button class="btn dark">Save product</button></form><?php include '../includes/footer.php';?>